class stringx {
    char *chars;
    void *my_buf;
public:
    stringx(const char *, int = -1);
};

class game {
    char pad[552];
    int beachid;
public:
    int get_beach_id(void) { return beachid; }
};

extern game *g_game_ptr;

enum { BEACH_MAVERICKS = 6 };

class JudgingSystem {
public:
    struct RUN {
        float regionScores[3];

        float GetAverageScore(void) const
        {
            if (g_game_ptr->get_beach_id() != BEACH_MAVERICKS)
                return (regionScores[0]+regionScores[1]+regionScores[2])/3.0f;
            else
                return (regionScores[0]+regionScores[1])/2.0f;
        }
    };

    struct RESULT {
        RUN runs[3];
        int rank;
    };

private:
    char pad[124];
    RESULT results[14];
    int currRunIdx;
    bool over;

public:
    RESULT * GetCompetitionResults(void) { return results; }
    int GetCurrRunIdx(void) const { return currRunIdx; }
    bool IsCompetitionOver(void) const { return over; }
};

class beach {
public:
    JudgingSystem judges;
};

extern beach *g_beach_ptr;

int sprintf(char *, const char *, ...);

class IGOFrontEnd {
public:
    stringx GetCompStrRun(const int surferIdx, const int runIdx) const;
};

__asm__(".equ __7stringxPCci, 0x0034D438");

stringx IGOFrontEnd::GetCompStrRun(const int surferIdx, const int runIdx) const
{
	JudgingSystem::RESULT *	results = g_beach_ptr->judges.GetCompetitionResults();
	char	s[256] = "";

	if (runIdx < g_beach_ptr->judges.GetCurrRunIdx() || g_beach_ptr->judges.IsCompetitionOver())
		sprintf(s, "%.1f", results[surferIdx].runs[runIdx].GetAverageScore());
	else
		sprintf(s, " . ");

	return stringx(s);
}
